    explanation: 'TCP三次握手：1.客户端发送SYN（同步序号），请求建立连接。2.服务器回复SYN+ACK（同步+确认），确认客户端的SYN，同时发送自己的SYN。3.客户端回复ACK（确认），确认服务器的SYN，连接建立。第二次握手是SYN+ACK，既有确认又有同步。',
    knowledgeId: 'datacom-tcp-udp',
